-- migrate:up
--
-- Baseline schema for Serious Shift.
--
-- Squashed from the original sequential migrations 0001-0008 (see git history).
-- Generated with `dbmate up` against an empty database followed by pg_dump, so
-- it reflects the real post-0008 state -- notably without the concepts/tensions
-- tables that 0001 created and 0008 dropped.
--
-- Regenerate rather than hand-edit. Seed rows (thinkers, scrape_sources,
-- reputable_venues) use ON CONFLICT DO NOTHING so re-application is safe.

CREATE TABLE public.claims (
    id bigint NOT NULL,
    source_id bigint,
    thinker_id bigint,
    claim_text text NOT NULL,
    claim_type text,
    domain text,
    consumer_implication text,
    signal_strength text,
    specificity integer,
    quote text,
    claim_weight double precision,
    freshness_score double precision,
    duplicate_of bigint,
    has_statistic boolean DEFAULT false,
    statistic text,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT claims_signal_strength_check CHECK ((signal_strength = ANY (ARRAY['noise'::text, 'background'::text, 'signal'::text, 'strong_signal'::text]))),
    CONSTRAINT claims_specificity_check CHECK (((specificity >= 1) AND (specificity <= 5)))
);

ALTER TABLE public.claims ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.claims_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.documents (
    key text NOT NULL,
    body jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now()
);

CREATE TABLE public.domain_flows (
    id bigint NOT NULL,
    source_id text NOT NULL,
    target_id text NOT NULL,
