CREATE TABLE public.predictions (
    id bigint NOT NULL,
    prediction_id text NOT NULL,
    claim_id bigint,
    thinker_id bigint,
    source_id bigint,
    claim_text text NOT NULL,
    timeframe text,
    domain text,
    specificity integer,
    falsifiable boolean DEFAULT true,
    status text DEFAULT 'pending'::text,
    consensus_alignment double precision,
    evaluation_date date,
    evaluation_notes text,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT predictions_consensus_alignment_check CHECK (((consensus_alignment >= (0.0)::double precision) AND (consensus_alignment <= (1.0)::double precision))),
    CONSTRAINT predictions_specificity_check CHECK (((specificity >= 1) AND (specificity <= 5))),
    CONSTRAINT predictions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'partially_true'::text, 'true'::text, 'false'::text, 'expired'::text])))
);

ALTER TABLE public.predictions ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.predictions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

