    source_type text,
    platform text,
    url text,
    summary text,
    full_text text,
    consumer_implication text,
    signal_strength text,
    novelty text,
    keynote_impact text,
    confidence text,
    filename text,
    source_depth integer,
    created_at timestamp with time zone DEFAULT now(),
    doi text,
    venue text,
    external_id text,
    citation_count integer,
    peer_reviewed boolean,
    authors jsonb,
    authority double precision,
    CONSTRAINT sources_signal_strength_check CHECK ((signal_strength = ANY (ARRAY['noise'::text, 'background'::text, 'signal'::text, 'strong_signal'::text])))
);

ALTER TABLE public.sources ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.sources_id_seq
