CREATE TABLE public.thinkers (
    id bigint NOT NULL,
    name text NOT NULL,
    affiliation text,
    domain text,
    agi_timeline text,
    economic_worldview text,
    consumer_behavior_stance text,
    importance_score integer,
    signal_quality text,
    credibility_score double precision DEFAULT 50.0,
    prediction_accuracy double precision,
    outlier_factor double precision,
    bio text,
    image_url text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    entity_kind text DEFAULT 'person'::text NOT NULL,
    reputation_tier integer,
    authority_score double precision,
    external_ids jsonb,
    discovered boolean DEFAULT false NOT NULL,
    CONSTRAINT thinkers_importance_score_check CHECK (((importance_score >= 1) AND (importance_score <= 10))),
    CONSTRAINT thinkers_reputation_tier_check CHECK (((reputation_tier >= 1) AND (reputation_tier <= 5)))
);

ALTER TABLE public.thinkers ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.thinkers_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

