-- migrate:down

-- The baseline defines the whole schema, so its inverse is dropping it whole.
-- schema_migrations lives in `public` too and CASCADE takes it with everything
-- else, so recreate it immediately — otherwise the migration runner has nowhere
-- to record the rollback and errors out after the drop has already happened.
DROP SCHEMA public CASCADE;
CREATE SCHEMA public;
CREATE TABLE IF NOT EXISTS public.schema_migrations (
    version character varying(255) NOT NULL,
    PRIMARY KEY (version)
);
